  -- 01. Caso: hipotiroidismo descompensado por interacciones y cambio de marca
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La TSH que subió sin cambiar la dosis","texto":"Una paciente con hipotiroidismo estable cambia de marca de levotiroxina y empieza a tomar calcio y omeprazol. La TSH sube y los síntomas vuelven. El caso integra absorción, interacciones, adherencia y educación con recursos de Feliz Sin Tiroides."},"objetivos":["Analizar la descompensación tiroidea.","Revisar interacciones y marca.","Ajustar la dosis con criterio.","Educar y recomendar recursos de FST."],"conceptos":[{"icono":"Pill","termino":"Levotiroxina","definicion":"Sensible a la absorción y la marca."},{"icono":"AlertTriangle","termino":"Interacción","definicion":"Calcio, hierro, IBP y café."},{"icono":"TestTube","termino":"TSH","definicion":"Guía el ajuste."},{"icono":"Users","termino":"Adherencia","definicion":"Horario y constancia."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente tiene hipotiroidismo tratado con levotiroxina en dosis estable. Tras un cambio de marca comienza con calcio para la osteoporosis y omeprazol por reflujo. Refiere fatiga, estreñimiento, piel seca y aumento de peso. La TSH está alta y la T4 libre baja.","El QF revisa la hora de la toma, la marca, la adherencia y todas las interacciones. La descompensación no se explica por una sola causa: el cambio de marca, el calcio, el inhibidor de la bomba y quizá el café o la fibra contribuyen."]},{"titulo":"Intervención","parrafos":["Se separa el calcio y el omeprazol al menos cuatro horas de la levotiroxina, se revisa el horario y se recomienda una marca constante. Se verifica la técnica de la toma en ayunas y se descartan otras causas de malabsorción.","Si la TSH sigue alta tras corregir la absorción, se ajusta la dosis en 12,5-25 µg y se controla en seis a ocho semanas. El QF documenta la intervención y coordina con el médico."]},{"titulo":"Educación y recursos","parrafos":["La paciente recibe instrucciones escritas y se refuerza la comprensión. Feliz Sin Tiroides ofrece la guía Levotiroxina sin sorpresas, que explica cómo organizar la toma y reconocer interferencias, y la guía completa para recién diagnosticados con hipotiroidismo, útil para entender el diagnóstico y los controles.","Recomendar estos recursos complementa la educación de la farmacia y ayuda a que el paciente llegue a la consulta con mejores preguntas. La educación mejora la adherencia y reduce las descompensaciones."]}],"errores":[{"error":"Cambiar de marca sin control.","correccion":"Puede alterar la TSH."},{"error":"No separar el calcio.","correccion":"Reduce la absorción."},{"error":"No educar sobre el horario.","correccion":"La toma con alimentos falla."}],"comprueba":[{"pregunta":"¿Qué interacciones revisar?","respuesta":"Calcio, hierro, IBP y café."},{"pregunta":"¿Cuándo se controla la TSH?","respuesta":"A las 6-8 semanas."},{"pregunta":"¿Qué guía de FST se recomienda?","respuesta":"Levotiroxina sin sorpresas."}],"resumen":["La descompensación tiene causas revisables.","La absorción y la marca importan.","La TSH guía el ajuste.","Las guías de FST refuerzan la educación."],"referencias":[{"cita":"Feliz Sin Tiroides. Levotiroxina sin sorpresas. Guía educativa.","url":"https://go.hotmart.com/X107038343S?dp=1"},{"cita":"Feliz Sin Tiroides. Guía completa para recién diagnosticados con hipotiroidismo.","url":"https://go.hotmart.com/C107034583V?dp=1"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Ficha con TSH, interacciones y plan de ajuste.","alt":"Caso de hipotiroidismo descompensado"}],"keywords":["hipotiroidismo descompensado","levotiroxina interacciones","feliz sin tiroides","tsh"],"mapa":{"centro":"Hipotiroidismo","ramas":[{"titulo":"Absorción","icono":"Timer","nodos":["Ayunas","Agua","Marca"]},{"titulo":"Interacción","icono":"AlertTriangle","nodos":["Calcio","Omeprazol","Café"]},{"titulo":"Clínica","icono":"Activity","nodos":["Fatiga","Peso","Frío","Piel"]},{"titulo":"Plan","icono":"FileCheck","nodos":["Separar","Ajustar","Control"]}]},"proceso":{"titulo":"Resolver la descompensación","intro":"","pasos":[{"titulo":"Revisar","detalle":"Marca, horario y adherencia.","icono":"Eye","evidencia":"Entrevista."},{"titulo":"Interacción","detalle":"Calcio, IBP y café.","icono":"AlertTriangle","evidencia":"Lista."},{"titulo":"Separar","detalle":"Al menos 4 horas.","icono":"Timer","evidencia":"Consejería."},{"titulo":"Ajustar","detalle":"TSH y dosis.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Educar","detalle":"Guías de FST.","icono":"Users","evidencia":"Entrega."}]},"caso":{"titulo":"Calcio y omeprazol","contexto":"Paciente con levotiroxina, calcio y omeprazol que presenta TSH elevada y síntomas.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Aumentar la dosis sin revisar.","correcta":false,"retro":"Primero se corrige la absorción."},{"texto":"Separar interacciones y revisar la marca.","correcta":true,"retro":"Aborda la causa."},{"texto":"Suspender la levotiroxina.","correcta":false,"retro":"Empeora el hipotiroidismo."}]}}$j$::jsonb;
