  -- 02. Glucocorticoides: mecanismo, equivalencias y efectos adversos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La dosis que no es equivalente","texto":"Prednisona 5 mg, metilprednisolona 4 mg y dexametasona 0,75 mg tienen potencia similar. Confundir las equivalencias puede causar sobretratamiento o insuficiencia suprarrenal. La conversión correcta es parte de la seguridad."},"objetivos":["Explicar el mecanismo.","Aplicar las equivalencias.","Reconocer los efectos adversos.","Individualizar la vía y la dosis."],"conceptos":[{"icono":"Pill","termino":"Glucocorticoide","definicion":"Antiinflamatorio e inmunosupresor."},{"icono":"Calculator","termino":"Equivalencia","definicion":"Prednisona 5 mg ≈ dexametasona 0,75 mg."},{"icono":"AlertTriangle","termino":"Adversos","definicion":"Hiperglucemia, infección, hueso."},{"icono":"Activity","termino":"Eje HHS","definicion":"Puede suprimirse con el uso prolongado."}],"secciones":[{"titulo":"Mecanismo y equivalencias","parrafos":["Los glucocorticoides se unen al receptor de glucocorticoides y modifican la transcripción de genes inflamatorios e inmunes. Su efecto depende de la dosis, la duración y la vía. La potencia relativa permite convertir entre moléculas: hidrocortisona 20 mg, prednisona 5 mg, prednisolona 5 mg, metilprednisolona 4 mg y dexametasona 0,75 mg son aproximadamente equivalentes.","La dexametasona no tiene efecto mineralocorticoide significativo y tiene una vida media larga. La prednisona y la prednisolona son las más usadas por vía oral. La hidrocortisona se usa en la insuficiencia suprarrenal por su efecto mineralocorticoide."]},{"titulo":"Efectos adversos","parrafos":["Los efectos adversos incluyen hiperglucemia, aumento del apetito y del peso, retención de líquidos, hipertensión, osteoporosis, cataratas, glaucoma, adelgazamiento de la piel, equimosis, acné, insomnio y cambios del ánimo. También aumentan el riesgo de infecciones y pueden reactivar tuberculosis o hepatitis.","El riesgo depende de la dosis y del tiempo. Se usa la dosis mínima eficaz y la menor duración posible. En tratamientos prolongados se añade calcio, vitamina D y medidas de prevención ósea."]},{"titulo":"Uso seguro","parrafos":["La vía oral se usa cuando es posible; la intravenosa en situaciones graves. La toma matutina imita el ritmo circadiano y reduce el insomnio. La dosis se individualiza y se revisa la necesidad de forma periódica.","El QF revisa interacciones, glucemia, presión y riesgo infeccioso. La educación incluye no suspender bruscamente y reconocer signos de insuficiencia suprarrenal."]}],"errores":[{"error":"Confundir equivalencias.","correccion":"Puede causar toxicidad o insuficiencia."},{"error":"Suspender bruscamente.","correccion":"Riesgo de crisis suprarrenal."},{"error":"No prevenir la osteoporosis.","correccion":"El uso prolongado la causa."}],"comprueba":[{"pregunta":"¿Cuánto equivale prednisona 5 mg?","respuesta":"Dexametasona 0,75 mg."},{"pregunta":"¿Qué efecto mineralocorticoide tiene la dexametasona?","respuesta":"Mínimo."},{"pregunta":"¿Cuándo se retira gradual?","respuesta":"Tras uso prolongado."}],"resumen":["Las equivalencias evitan errores.","Los efectos adversos dependen de dosis y tiempo.","La toma matutina reduce el insomnio.","El retiro es gradual si hubo supresión."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Prednisona Kern Pharma 30 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/76734/FT_76734.html"}],"imagenes":[{"ubicacion":"Glucocorticoides","descripcion":"Tabla de equivalencias y efectos adversos.","alt":"Glucocorticoides equivalencias y efectos"}],"keywords":["glucocorticoides","prednisona","dexametasona","equivalencias"],"mapa":{"centro":"Glucocorticoides","ramas":[{"titulo":"Potencia","icono":"Calculator","nodos":["Hidrocortisona","Prednisona","Dexametasona"]},{"titulo":"Efectos","icono":"AlertTriangle","nodos":["Glucosa","Infección","Hueso","Piel"]},{"titulo":"Eje","icono":"Activity","nodos":["Supresión","Retiro","Estrés"]},{"titulo":"Uso","icono":"Target","nodos":["Inflamación","Asma","Autoinmune"]}]},"proceso":{"titulo":"Checklist de glucocorticoides","intro":"","pasos":[{"titulo":"Indicación","detalle":"Inflamatoria o endocrina.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Equivalencia","detalle":"Convertir la dosis.","icono":"Calculator","evidencia":"Cálculo."},{"titulo":"Duración","detalle":"La menor posible.","icono":"Timer","evidencia":"Plan."},{"titulo":"Adversos","detalle":"Glucosa, hueso e infección.","icono":"AlertTriangle","evidencia":"Control."},{"titulo":"Retiro","detalle":"Gradual si es prolongado.","icono":"Repeat","evidencia":"Esquema."}]},"caso":{"titulo":"Conversión de prednisona","contexto":"Paciente que recibe prednisona 20 mg y requiere un equivalente de dexametasona.","pregunta":"¿Qué dosis es aproximadamente equivalente?","opciones":[{"texto":"3 mg de dexametasona.","correcta":true,"retro":"20 mg de prednisona ≈ 3 mg de dexametasona."},{"texto":"20 mg de dexametasona.","correcta":false,"retro":"Sería una sobredosis."},{"texto":"0,75 mg de dexametasona.","correcta":false,"retro":"Equivale a 5 mg de prednisona."}]}}$j$::jsonb;
