  -- 03. Supresión del eje HHS, retiro gradual y dosis de estrés
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El paciente que no responde al estrés","texto":"Tras meses de prednisona, un paciente suspende el fármaco y presenta debilidad, hipotensión y náuseas. El eje suprarrenal estaba suprimido. El retiro gradual y la dosis de estrés previenen la crisis."},"objetivos":["Reconocer la supresión del eje.","Aplicar el retiro gradual.","Indicar la dosis de estrés.","Educar al paciente."],"conceptos":[{"icono":"Activity","termino":"Supresión","definicion":"El eje deja de responder al estrés."},{"icono":"Repeat","termino":"Retiro","definicion":"Reducción gradual."},{"icono":"Syringe","termino":"Estrés","definicion":"Dosis extra en enfermedad o cirugía."},{"icono":"AlertTriangle","termino":"Crisis","definicion":"Hipotensión, náuseas e hipoglucemia."}],"secciones":[{"titulo":"Supresión","parrafos":["El uso de glucocorticoides por más de tres semanas, a dosis altas o en horario nocturno puede suprimir el eje hipotálamo-hipófisis-suprarrenal. El eje deja de producir cortisol y el paciente depende del fármaco exógeno. La recuperación puede tardar meses.","La supresión se sospecha por síntomas de insuficiencia suprarrenal al reducir o suspender: debilidad, fatiga, náuseas, hipotensión, hipoglucemia e hiperpigmentación. El cortisol matutino y la prueba de estimulación con ACTH ayudan a confirmar."]},{"titulo":"Retiro gradual","parrafos":["El retiro se hace de forma gradual, con reducciones de 2,5-5 mg de prednisona cada una a dos semanas, más lento al final. Si el paciente tiene síntomas, se vuelve a la dosis previa y se reevalúa. No se debe suspender de golpe después de un uso prolongado.","En dosis fisiológicas se puede usar hidrocortisona para imitar el ritmo. El QF revisa la adherencia y educa sobre los síntomas de insuficiencia suprarrenal."]},{"titulo":"Dosis de estrés","parrafos":["Durante una enfermedad aguda, cirugía o trauma, el paciente necesita una dosis extra de glucocorticoides. La hidrocortisona es la opción habitual en el contexto agudo. La dosis depende de la gravedad y se indica por el equipo tratante.","El paciente debe llevar una tarjeta o identificación de riesgo suprarrenal y saber cuándo consultar. La educación de la familia también es importante. La crisis suprarrenal es una emergencia. La dosis y la vía se ajustan a la gravedad y al contexto clínico; el paciente debe consultar antes de modificar el esquema por su cuenta."]}],"errores":[{"error":"Suspender bruscamente.","correccion":"Riesgo de crisis."},{"error":"No indicar dosis de estrés.","correccion":"Puede descompensar."},{"error":"No educar a la familia.","correccion":"La crisis requiere ayuda."}],"comprueba":[{"pregunta":"¿Cuándo se suprime el eje?","respuesta":"Con uso prolongado o dosis altas."},{"pregunta":"¿Cómo se retira?","respuesta":"De forma gradual."},{"pregunta":"¿Qué es la dosis de estrés?","respuesta":"Dosis extra en enfermedad o cirugía."}],"resumen":["El eje puede suprimirse.","El retiro es gradual y supervisado.","La dosis de estrés previene la crisis.","La educación del paciente es clave."],"referencias":[{"cita":"Endocrine Society. Clinical Practice Guideline: Diagnosis and Treatment of Primary Adrenal Insufficiency. J Clin Endocrinol Metab. 2016.","url":"https://www.endocrine.org/clinical-practice-guidelines/adrenal-insufficiency"}],"imagenes":[{"ubicacion":"Eje HHS","descripcion":"Retiro gradual y dosis de estrés.","alt":"Supresión del eje suprarrenal"}],"keywords":["supresión eje hhs","retiro glucocorticoides","dosis de estrés","crisis suprarrenal"],"mapa":{"centro":"Eje HHS","ramas":[{"titulo":"Riesgo","icono":"AlertTriangle","nodos":[">3 semanas","Dosis alta","Uso nocturno"]},{"titulo":"Retiro","icono":"Repeat","nodos":["Gradual","Síntomas","Cortisol"]},{"titulo":"Estrés","icono":"Syringe","nodos":["Cirugía","Infección","Trauma"]},{"titulo":"Educación","icono":"Users","nodos":["Alerta","Tarjeta","Consulta"]}]},"proceso":{"titulo":"Retirar con seguridad","intro":"","pasos":[{"titulo":"Calcular","detalle":"Duración y dosis acumulada.","icono":"Calculator","evidencia":"Historia."},{"titulo":"Reducir","detalle":"Gradual y supervisado.","icono":"Repeat","evidencia":"Esquema."},{"titulo":"Síntomas","detalle":"Debilidad e hipotensión.","icono":"AlertTriangle","evidencia":"Entrevista."},{"titulo":"Estrés","detalle":"Dosis extra si enfermedad.","icono":"Syringe","evidencia":"Plan."},{"titulo":"Educar","detalle":"Tarjeta y consulta.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Suspensión brusca","contexto":"Paciente con prednisona por seis meses que suspende de golpe y presenta hipotensión y náuseas.","pregunta":"¿Qué sospecha el QF?","opciones":[{"texto":"Crisis suprarrenal.","correcta":true,"retro":"El eje estaba suprimido."},{"texto":"Efecto normal del retiro.","correcta":false,"retro":"Es una emergencia."},{"texto":"Falta de adherencia.","correcta":false,"retro":"El cuadro es de insuficiencia."}]}}$j$::jsonb;
