  -- 04. Introducción a la unidad: remodelado óseo y regulación hipofisaria
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"El hueso que se renueva","texto":"El hueso está en remodelado continuo: los osteoclastos lo reabsorben y los osteoblastos lo forman. Cuando el equilibrio se rompe, aparece la osteoporosis. Entender el remodelado explica los bisfosfonatos, el denosumab y la teriparatida."},"objetivos":["Explicar el remodelado óseo.","Reconocer las dianas farmacológicas.","Conectar hueso e hipófisis.","Aplicar el concepto de secuencia."],"conceptos":[{"icono":"Activity","termino":"Osteoclasto","definicion":"Reabsorbe hueso; diana de antirresortivos."},{"icono":"ShieldCheck","termino":"Osteoblasto","definicion":"Forma hueso; diana de anabólicos."},{"icono":"Network","termino":"RANKL","definicion":"Vía que activa los osteoclastos."},{"icono":"Timer","termino":"Secuencia","definicion":"Orden de los fármacos."}],"secciones":[{"titulo":"Remodelado","parrafos":["El remodelado óseo es un ciclo coordinado de reabsorción y formación. Los osteoclastos reabsorben hueso y los osteoblastos lo reconstruyen. El equilibrio depende de hormonas, carga mecánica, calcio, vitamina D y factores locales.","La vía RANKL-RANK activa los osteoclastos; la osteoprotegerina la inhibe. La vía Wnt y la esclerostina regulan la formación. La pérdida de estrógeno en la menopausia y el uso de glucocorticoides inclinan el equilibrio hacia la reabsorción."]},{"titulo":"Dianas farmacológicas","parrafos":["Los bisfosfonatos y el denosumab son antirresortivos: reducen la actividad osteoclástica. La teriparatida y el romosozumab son anabólicos: estimulan la formación. La secuencia importa: después de un anabólico se usa un antirresortivo para mantener la ganancia.","El calcio y la vitamina D son la base. La terapia hormonal de la menopausia también protege el hueso, pero se decide por otros criterios. La hipófisis regula el crecimiento y otras hormonas que afectan el hueso."]},{"titulo":"Aplicación","parrafos":["El QF revisa la indicación, la secuencia, la adherencia y la seguridad. Los antirresortivos requieren control de calcio y vitamina D; los anabólicos tienen límites de duración. La educación sobre la administración es clave.","La osteoporosis es silenciosa hasta la fractura. La prevención y el tratamiento oportuno reducen la morbimortalidad. El QF revisa también la adherencia a calcio y vitamina D, porque sin ellos los fármacos pierden eficacia y pueden causar hipocalcemia."]}],"errores":[{"error":"Indicar antirresortivo sin calcio.","correccion":"Puede causar hipocalcemia."},{"error":"Olvidar la secuencia.","correccion":"Se pierde la ganancia."},{"error":"No evaluar el riesgo.","correccion":"Se subtrata."}],"comprueba":[{"pregunta":"¿Qué hace el osteoclasto?","respuesta":"Reabsorbe hueso."},{"pregunta":"¿Qué es la vía RANKL?","respuesta":"Activa los osteoclastos."},{"pregunta":"¿Qué fármacos son anabólicos?","respuesta":"Teriparatida y romosozumab."}],"resumen":["El hueso se remodela continuamente.","Los antirresortivos y anabólicos actúan distinto.","La secuencia importa.","Calcio y vitamina D son la base."],"referencias":[{"cita":"Endocrine Society. Pharmacological Management of Osteoporosis in Postmenopausal Women: Guideline. J Clin Endocrinol Metab. 2019.","url":"https://www.endocrine.org/clinical-practice-guidelines/osteoporosis"}],"imagenes":[{"ubicacion":"Unidad 4","descripcion":"Remodelado óseo y dianas farmacológicas.","alt":"Remodelado óseo y osteoporosis"}],"keywords":["remodelado óseo","osteoclasto","rankl","osteoporosis"],"mapa":{"centro":"Remodelado óseo","ramas":[{"titulo":"Células","icono":"Activity","nodos":["Osteoclasto","Osteoblasto","Osteocito"]},{"titulo":"Vías","icono":"Network","nodos":["RANKL","OPG","Wnt"]},{"titulo":"Fármacos","icono":"Pill","nodos":["Bisfosfonato","Denosumab","Teriparatida"]},{"titulo":"Regulación","icono":"Timer","nodos":["PTH","Vitamina D","Estrógeno"]}]},"proceso":{"titulo":"Elegir terapia ósea","intro":"","pasos":[{"titulo":"Riesgo","detalle":"Fractura y DMO.","icono":"LineChart","evidencia":"Evaluación."},{"titulo":"Base","detalle":"Calcio y vitamina D.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Fármaco","detalle":"Antirresortivo o anabólico.","icono":"Target","evidencia":"Decisión."},{"titulo":"Secuencia","detalle":"Mantener la ganancia.","icono":"Timer","evidencia":"Plan."},{"titulo":"Seguir","detalle":"Adherencia y seguridad.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Fractura por fragilidad","contexto":"Paciente con fractura de cadera y osteoporosis.","pregunta":"¿Qué enfoque es correcto?","opciones":[{"texto":"Solo calcio.","correcta":false,"retro":"No reduce el riesgo de fractura."},{"texto":"Antirresortivo con base de calcio y vitamina D.","correcta":true,"retro":"Reduce nuevas fracturas."},{"texto":"Nada; ya tuvo la fractura.","correcta":false,"retro":"El riesgo persiste."}]}}$j$::jsonb;
