  -- 05. Calcio, vitamina D y bisfosfonatos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El bisfosfonato que no se absorbe","texto":"Un paciente toma alendronato con el desayuno y no mejora su densidad ósea. Los bisfosfonatos orales exigen técnica: en ayunas, con agua y sin acostarse después. La educación cambia el resultado."},"objetivos":["Aplicar la base de calcio y vitamina D.","Usar correctamente los bisfosfonatos.","Reconocer contraindicaciones y efectos.","Monitorizar la respuesta."],"conceptos":[{"icono":"Pill","termino":"Calcio","definicion":"1000-1200 mg al día."},{"icono":"Sun","termino":"Vitamina D","definicion":"800-1000 UI al día."},{"icono":"ShieldCheck","termino":"Bisfosfonato","definicion":"Antirresortivo de primera línea."},{"icono":"AlertTriangle","termino":"Esofagitis","definicion":"Riesgo si no se toma erguido."}],"secciones":[{"titulo":"Calcio y vitamina D","parrafos":["La ingesta adecuada de calcio es de 1000-1200 mg al día, preferiblemente de la dieta. La vitamina D se recomienda en 800-1000 UI al día en personas con riesgo o tratamiento para osteoporosis. Se ajusta según los niveles y la exposición solar.","La suplementación no sustituye el tratamiento antirresortivo en la osteoporosis establecida. El QF revisa la ingesta, la adherencia y las interacciones."]},{"titulo":"Bisfosfonatos","parrafos":["Los bisfosfonatos orales, como alendronato 70 mg semanal o risedronato, se toman en ayunas con un vaso de agua, al menos 30 minutos antes de comer y sin acostarse después. El ácido zoledrónico se administra por vía intravenosa una vez al año. Son antirresortivos de primera línea.","Se evitan en trastornos esofágicos, hipocalcemia y TFG muy baja. Los efectos adversos incluyen síntomas digestivos, hipocalcemia, osteonecrosis de mandíbula y fracturas atípicas con uso prolongado. La revisión odontológica y la educación reducen el riesgo."]},{"titulo":"Seguimiento","parrafos":["La densidad mineral ósea se mide cada uno a dos años. Se revisan calcio, vitamina D, función renal y adherencia. La duración del tratamiento se individualiza: algunos pacientes pueden suspender después de varios años, otros continúan.","El QF enseña la técnica, revisa la tolerancia y detecta interacciones. La educación es especialmente importante porque el fármaco no produce síntomas visibles."]}],"errores":[{"error":"Tomar el bisfosfonato con comida.","correccion":"No se absorbe."},{"error":"Acostarse después.","correccion":"Riesgo de esofagitis."},{"error":"No revisar el calcio.","correccion":"Hipocalcemia."}],"comprueba":[{"pregunta":"¿Cómo se toma el alendronato?","respuesta":"En ayunas, con agua y erguido 30 min."},{"pregunta":"¿Qué se controla?","respuesta":"Calcio, vitamina D, renal y DMO."},{"pregunta":"¿Qué efectos son raros pero graves?","respuesta":"ONJ y fracturas atípicas."}],"resumen":["Calcio y vitamina D son la base.","Los bisfosfonatos exigen técnica.","La seguridad digestiva y renal importa.","El seguimiento mide DMO y adherencia."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Alendronato Semanal Normon 70 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/65647/FT_65647.html"}],"imagenes":[{"ubicacion":"Bisfosfonatos","descripcion":"Técnica de administración y controles.","alt":"Calcio, vitamina D y bisfosfonatos"}],"keywords":["alendronato","bisfosfonatos","calcio","vitamina d","osteoporosis"],"mapa":{"centro":"Hueso","ramas":[{"titulo":"Base","icono":"Pill","nodos":["Calcio","Vitamina D","Dieta"]},{"titulo":"Bisfosfonatos","icono":"ShieldCheck","nodos":["Alendronato","Risedronato","Zoledrónico"]},{"titulo":"Técnica","icono":"Timer","nodos":["Ayunas","Agua","30 min"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Esofagitis","Hipocalcemia","ONJ"]}]},"proceso":{"titulo":"Checklist de bisfosfonatos","intro":"","pasos":[{"titulo":"Indicación","detalle":"Osteoporosis o riesgo.","icono":"Target","evidencia":"DMO."},{"titulo":"Calcio","detalle":"Dieta y suplemento.","icono":"Pill","evidencia":"Ingesta."},{"titulo":"Técnica","detalle":"Ayunas y erguido.","icono":"Timer","evidencia":"Demostración."},{"titulo":"Renal","detalle":"TFG antes de iniciar.","icono":"Droplets","evidencia":"Laboratorio."},{"titulo":"Seguir","detalle":"DMO y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Alendronato con desayuno","contexto":"Paciente que toma alendronato con el desayuno y presenta molestias digestivas.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Mantener la técnica.","correcta":false,"retro":"Así no se absorbe y daña el esófago."},{"texto":"Corregir la técnica y revisar la tolerancia.","correcta":true,"retro":"Mejora la absorción y la seguridad."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Aumenta el riesgo."}]}}$j$::jsonb;
