  -- 06. Denosumab, teriparatida y romosozumab
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cuando se suspende el denosumab","texto":"El denosumab reduce el riesgo de fractura, pero al suspenderlo la densidad ósea cae rápido y aumenta el riesgo vertebral. La transición a un bisfosfonato es parte del plan. La secuencia importa tanto como la elección."},"objetivos":["Diferenciar los fármacos óseos.","Aplicar la secuencia.","Reconocer efectos adversos.","Educar y monitorizar."],"conceptos":[{"icono":"ShieldCheck","termino":"Denosumab","definicion":"Anti-RANKL; antirresortivo potente."},{"icono":"Activity","termino":"Teriparatida","definicion":"Anabólico; forma hueso."},{"icono":"Target","termino":"Romosozumab","definicion":"Anti-esclerostina; anabólico."},{"icono":"Repeat","termino":"Secuencia","definicion":"Anabólico seguido de antirresortivo."}],"secciones":[{"titulo":"Denosumab","parrafos":["El denosumab es un anticuerpo monoclonal contra RANKL que reduce la actividad osteoclástica. Se administra 60 mg por vía subcutánea cada seis meses. Es potente y útil en pacientes con intolerancia a bisfosfonatos o función renal reducida.","Al suspenderlo, la densidad ósea cae rápidamente y el riesgo de fracturas vertebrales aumenta. Por eso se debe transicionar a un bisfosfonato u otro tratamiento. Se controla calcio y vitamina D, y se vigila la osteonecrosis de mandíbula."]},{"titulo":"Anabólicos","parrafos":["La teriparatida es un fragmento de PTH que estimula la formación ósea. Se administra 20 µg subcutáneos al día por un máximo de dos años. Puede causar hipercalcemia, náuseas y mareo. Se usa en osteoporosis grave o con fracturas múltiples.","El romosozumab inhibe la esclerostina y aumenta la formación y reduce la reabsorción. Se administra 210 mg subcutáneos al mes por 12 meses. Tiene una advertencia cardiovascular y se evita en pacientes con infarto o accidente cerebrovascular reciente."]},{"titulo":"Secuencia y seguimiento","parrafos":["El tratamiento se planifica como una secuencia: los anabólicos seguidos de antirresortivos para mantener la ganancia. En osteoporosis grave se puede iniciar con un anabólico. La elección depende del riesgo, la seguridad y el acceso.","El QF revisa la administración, la adherencia y los efectos adversos. La educación sobre la duración y la transición evita interrupciones peligrosas."]}],"errores":[{"error":"Suspender denosumab sin transición.","correccion":"Riesgo de fracturas."},{"error":"Usar romosozumab en cardiopatía reciente.","correccion":"Advertencia cardiovascular."},{"error":"No controlar calcio.","correccion":"Hipocalcemia con antirresortivos."}],"comprueba":[{"pregunta":"¿Cada cuánto se aplica denosumab?","respuesta":"Cada seis meses."},{"pregunta":"¿Cuánto dura la teriparatida?","respuesta":"Máximo dos años."},{"pregunta":"¿Qué se hace al suspender denosumab?","respuesta":"Transición a bisfosfonato."}],"resumen":["Denosumab es potente y requiere transición.","Los anabólicos forman hueso.","La secuencia mantiene la ganancia.","La seguridad cardiovascular importa."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Prolia 60 mg solución inyectable en jeringa precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/10411001/FT_10411001.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Forsteo 20 microgramos/80 microlitros solución inyectable (teriparatida).","url":"https://cima.aemps.es/cima/dochtml/ft/02397001/FT_02397001.html"}],"imagenes":[{"ubicacion":"Terapias óseas","descripcion":"Secuencia de anabólicos y antirresortivos.","alt":"Denosumab, teriparatida y romosozumab"}],"keywords":["denosumab","teriparatida","romosozumab","secuencia osteoporosis"],"mapa":{"centro":"Terapias óseas","ramas":[{"titulo":"Denosumab","icono":"ShieldCheck","nodos":["60 mg","6 meses","Rebote"]},{"titulo":"Teriparatida","icono":"Activity","nodos":["20 µg","Diaria","2 años"]},{"titulo":"Romosozumab","icono":"Target","nodos":["210 mg","Mensual","12 meses"]},{"titulo":"Secuencia","icono":"Repeat","nodos":["Anabólico","Antirresortivo","Control"]}]},"proceso":{"titulo":"Planificar la secuencia","intro":"","pasos":[{"titulo":"Riesgo","detalle":"Fracturas y DMO.","icono":"LineChart","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"Antirresortivo o anabólico.","icono":"Target","evidencia":"Decisión."},{"titulo":"Administrar","detalle":"Vía y frecuencia.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Transición","detalle":"Evitar rebote.","icono":"Repeat","evidencia":"Plan."},{"titulo":"Seguir","detalle":"Calcio, DMO y efectos.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Suspensión de denosumab","contexto":"Paciente con denosumab que planea suspenderlo sin transición.","pregunta":"¿Qué riesgo existe?","opciones":[{"texto":"Pérdida rápida de densidad y fracturas vertebrales.","correcta":true,"retro":"El rebote es un riesgo real."},{"texto":"Ninguno.","correcta":false,"retro":"La suspensión sin transición es peligrosa."},{"texto":"Solo hipercalcemia.","correcta":false,"retro":"El problema principal es el rebote."}]}}$j$::jsonb;
