  -- 07. Caso: osteoporosis inducida por glucocorticoides y discontinuación de denosumab
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El hueso que paga la prednisona","texto":"Una mujer de 65 años toma prednisona por una enfermedad inflamatoria y presenta una fractura vertebral. La osteoporosis inducida por glucocorticoides requiere prevención y tratamiento. La secuencia y el retiro del glucocorticoide forman parte del plan."},"objetivos":["Reconocer la osteoporosis por glucocorticoides.","Aplicar la prevención y el tratamiento.","Manejar la discontinuación de denosumab.","Coordinar con el equipo."],"conceptos":[{"icono":"AlertTriangle","termino":"GIO","definicion":"Osteoporosis inducida por glucocorticoides."},{"icono":"ShieldCheck","termino":"Prevención","definicion":"Calcio, vitamina D y fármaco."},{"icono":"Repeat","termino":"Transición","definicion":"Evitar el rebote del denosumab."},{"icono":"Users","termino":"Educación","definicion":"Adherencia y caídas."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente toma prednisona a dosis de 10 mg al día por seis meses. Presenta dolor dorsal y una fractura vertebral. La osteoporosis inducida por glucocorticoides aparece pronto y depende de la dosis y la duración. Se evalúa el riesgo de fractura, la densidad ósea y los factores de caída.","Se revisa la dosis mínima eficaz del glucocorticoide y la posibilidad de reducirlo. La prevención incluye calcio, vitamina D, ejercicio y medidas para evitar caídas."]},{"titulo":"Tratamiento","parrafos":["En riesgo alto se indica un antirresortivo o un anabólico según la gravedad. Los bisfosfonatos son una opción frecuente; el denosumab se usa en pacientes seleccionados. Si se inicia denosumab, se planifica la transición a un bisfosfonato al suspenderlo para evitar el rebote.","La teriparatida puede ser útil en fracturas múltiples o riesgo muy alto. La duración y la secuencia se individualizan. El QF revisa la adherencia y la técnica de administración."]},{"titulo":"Seguimiento","parrafos":["Se controlan la densidad ósea, la aparición de nuevas fracturas, el calcio y la vitamina D. La educación incluye la técnica, la adherencia y la prevención de caídas. La coordinación con reumatología, endocrinología y atención primaria es clave.","El caso muestra que la osteoporosis por glucocorticoides es prevenible y tratable. La revisión del fármaco causal y la secuencia correcta evitan nuevas fracturas."]}],"errores":[{"error":"No prevenir la osteoporosis.","correccion":"Aparece temprano."},{"error":"Suspender denosumab sin transición.","correccion":"Riesgo de rebote."},{"error":"Suspender prednisona bruscamente.","correccion":"Crisis suprarrenal."}],"comprueba":[{"pregunta":"¿Qué causa la GIO?","respuesta":"El uso prolongado de glucocorticoides."},{"pregunta":"¿Qué incluye la prevención?","respuesta":"Calcio, vitamina D y fármaco."},{"pregunta":"¿Qué se hace al suspender denosumab?","respuesta":"Transición a bisfosfonato."}],"resumen":["La GIO es frecuente y prevenible.","El riesgo depende de dosis y tiempo.","La secuencia evita el rebote.","La coordinación y la educación son clave."],"referencias":[{"cita":"Endocrine Society. Pharmacological Management of Osteoporosis in Postmenopausal Women: Guideline. J Clin Endocrinol Metab. 2019.","url":"https://www.endocrine.org/clinical-practice-guidelines/osteoporosis"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Prevención y tratamiento de la osteoporosis por glucocorticoides.","alt":"Osteoporosis inducida por glucocorticoides"}],"keywords":["osteoporosis glucocorticoides","gio","denosumab transición","fractura vertebral"],"mapa":{"centro":"GIO","ramas":[{"titulo":"Riesgo","icono":"AlertTriangle","nodos":["Dosis","Duración","Edad"]},{"titulo":"Prevención","icono":"ShieldCheck","nodos":["Calcio","Vitamina D","Bisfosfonato"]},{"titulo":"Tratamiento","icono":"Pill","nodos":["Antirresortivo","Anabólico","Secuencia"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["DMO","Fracturas","Caídas"]}]},"proceso":{"titulo":"Manejo de GIO","intro":"","pasos":[{"titulo":"Riesgo","detalle":"Dosis y duración.","icono":"AlertTriangle","evidencia":"Historia."},{"titulo":"Prevenir","detalle":"Calcio y vitamina D.","icono":"ShieldCheck","evidencia":"Fórmula."},{"titulo":"Tratar","detalle":"Antirresortivo o anabólico.","icono":"Pill","evidencia":"Decisión."},{"titulo":"Secuencia","detalle":"Transición si denosumab.","icono":"Repeat","evidencia":"Plan."},{"titulo":"Seguir","detalle":"DMO y fracturas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Prednisona y fractura","contexto":"Mujer de 65 años con prednisona 10 mg por seis meses y fractura vertebral.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Solo calcio.","correcta":false,"retro":"No es suficiente en riesgo alto."},{"texto":"Prevención completa y tratamiento óseo.","correcta":true,"retro":"Reduce nuevas fracturas."},{"texto":"Suspender la prednisona de golpe.","correcta":false,"retro":"Riesgo de crisis suprarrenal."}]}}$j$::jsonb;
