  -- 08. Hormona de crecimiento (somatropina): indicaciones y seguimiento
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La hormona que no es para todos","texto":"La somatropina se usa en el déficit de hormona de crecimiento y en algunas condiciones específicas. No es un tratamiento para la baja talla sin diagnóstico ni un producto de bienestar. La indicación y el seguimiento son estrictos."},"objetivos":["Aplicar las indicaciones.","Reconocer la dosis y la vía.","Monitorizar IGF-1 y crecimiento.","Reconocer efectos adversos."],"conceptos":[{"icono":"Activity","termino":"Somatropina","definicion":"Hormona de crecimiento recombinante."},{"icono":"TestTube","termino":"IGF-1","definicion":"Marcador de respuesta y adherencia."},{"icono":"Target","termino":"Indicación","definicion":"Déficit documentado."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Edema, glucosa y presión intracraneal."}],"secciones":[{"titulo":"Indicaciones","parrafos":["La somatropina está indicada en el déficit de hormona de crecimiento en niños y adultos, en el síndrome de Turner, en niños pequeños para la edad gestacional que no catch-up y en otras condiciones específicas. La indicación debe estar documentada con pruebas de estimulación y seguimiento especializado.","No se usa para la baja talla idiopática sin evaluación ni como tratamiento de bienestar. La decisión es del endocrinólogo pediatra o del endocrinólogo de adultos."]},{"titulo":"Uso y seguimiento","parrafos":["Se administra por vía subcutánea, generalmente por la noche, con rotación de sitios. La dosis se ajusta por peso y respuesta. El IGF-1 se mide periódicamente para verificar adherencia y seguridad. En niños se monitoriza el crecimiento y la velocidad de talla.","La respuesta depende de la adherencia y de la causa. La educación sobre la técnica, la conservación y la rotación es esencial. El QF revisa la cadena de frío y el suministro."]},{"titulo":"Seguridad","parrafos":["Los efectos adversos incluyen edema, artralgia, hiperglucemia, hipertensión intracraneal benigna, escoliosis y, rara vez, complicaciones graves. No se usa en pacientes con tumores activos o en retinopatía diabética proliferativa sin control.","El seguimiento incluye glucosa, presión, IGF-1 y evaluación clínica. La suspensión se decide por el especialista. El QF documenta la adherencia y los efectos adversos. El ajuste y la suspensión corresponden al especialista; la farmacia acompaña la continuidad y la educación."]}],"errores":[{"error":"Usarla sin diagnóstico.","correccion":"No es un producto de bienestar."},{"error":"No controlar IGF-1.","correccion":"No se verifica adherencia."},{"error":"Romper la cadena de frío.","correccion":"Pierde efecto."}],"comprueba":[{"pregunta":"¿Cuál es la vía?","respuesta":"Subcutánea."},{"pregunta":"¿Qué se mide para el seguimiento?","respuesta":"IGF-1 y crecimiento."},{"pregunta":"¿Qué efectos adversos vigilar?","respuesta":"Edema, glucosa y HTIC."}],"resumen":["La somatropina tiene indicaciones precisas.","La técnica y la conservación importan.","El IGF-1 verifica la respuesta.","No es un tratamiento de bienestar."],"referencias":[{"cita":"Endocrine Society. Clinical Practice Guideline: Evaluation and Treatment of Adult Growth Hormone Deficiency. J Clin Endocrinol Metab. 2011.","url":"https://www.endocrine.org/clinical-practice-guidelines/adult-growth-hormone-deficiency"}],"imagenes":[{"ubicacion":"Hipófisis","descripcion":"Indicaciones y seguimiento de la somatropina.","alt":"Hormona de crecimiento somatropina"}],"keywords":["somatropina","hormona de crecimiento","igf-1","déficit gh"],"mapa":{"centro":"Somatropina","ramas":[{"titulo":"Indicación","icono":"Target","nodos":["Déficit GH","Turner","SGA"]},{"titulo":"Dosis","icono":"Syringe","nodos":["Subcutánea","Nocturna","Ajuste"]},{"titulo":"Control","icono":"TestTube","nodos":["IGF-1","Crecimiento","Adherencia"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Edema","Glucosa","HTIC"]}]},"proceso":{"titulo":"Checklist de somatropina","intro":"","pasos":[{"titulo":"Indicación","detalle":"Déficit documentado.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Técnica","detalle":"Subcutánea y rotación.","icono":"Syringe","evidencia":"Demostración."},{"titulo":"Conservación","detalle":"Cadena de frío.","icono":"Timer","evidencia":"Revisión."},{"titulo":"Control","detalle":"IGF-1 y crecimiento.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Seguridad","detalle":"Glucosa y presión.","icono":"AlertTriangle","evidencia":"Seguimiento."}]},"caso":{"titulo":"Baja talla sin diagnóstico","contexto":"Familia que solicita somatropina para un niño con baja talla sin evaluación.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Dispensar sin indicación.","correcta":false,"retro":"No está indicada."},{"texto":"Remitir a evaluación especializada.","correcta":true,"retro":"La indicación debe documentarse."},{"texto":"Usar una dosis de adulto.","correcta":false,"retro":"Es peligroso."}]}}$j$::jsonb;
