  -- 09. Desmopresina: diabetes insípida, enuresis y riesgo de hiponatremia
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La sed que no se puede ignorar","texto":"La desmopresina reduce la diuresis, pero puede causar hiponatremia grave si el paciente bebe en exceso. La educación sobre la sed y el control del sodio son parte del tratamiento."},"objetivos":["Aplicar las indicaciones.","Reconocer la vía y la dosis.","Prevenir la hiponatremia.","Educar al paciente y la familia."],"conceptos":[{"icono":"Droplets","termino":"Desmopresina","definicion":"Análogo de la vasopresina."},{"icono":"TestTube","termino":"Sodio","definicion":"Riesgo de hiponatremia."},{"icono":"Pill","termino":"Diabetes insípida","definicion":"Déficit central de ADH."},{"icono":"Users","termino":"Educación","definicion":"Sed y restricción de líquidos."}],"secciones":[{"titulo":"Indicaciones","parrafos":["La desmopresina es un análogo de la vasopresina que reduce la diuresis. Se usa en la diabetes insípida central, en la enuresis nocturna y en algunos trastornos hemorrágicos. La vía y la dosis dependen de la indicación.","En la diabetes insípida central reemplaza la ADH y reduce la poliuria y la sed. En la enuresis se usa por la noche. La respuesta se evalúa con la diuresis y el sodio."]},{"titulo":"Hiponatremia","parrafos":["El efecto antidiurético puede causar hiponatremia si el paciente bebe más de lo que excreta. El riesgo es mayor en niños, adultos mayores y pacientes con enfermedad aguda. La hiponatremia grave puede causar convulsiones y edema cerebral.","Se controla el sodio al inicio y durante el tratamiento. Se educa sobre la sed y la restricción de líquidos. En la enuresis se limita la ingesta nocturna y se suspende si hay enfermedad aguda."]},{"titulo":"Educación","parrafos":["El paciente y la familia deben reconocer los signos de hiponatremia: cefalea, náuseas, confusión, somnolencia y convulsiones. La educación sobre la dosis, la vía y la conservación es parte del plan.","El QF revisa la indicación, la adherencia y el sodio. La desmopresina es eficaz, pero exige control y educación. En la diabetes insípida central, la dosis se ajusta a la diuresis y a la sed; en la enuresis, se usa por la noche y se revisa la respuesta. La revisión de la medicación incluye otros fármacos que afectan el sodio, como diuréticos o antidepresivos. El control periódico permite detectar hiponatremia antes de que sea grave."]}],"errores":[{"error":"No controlar el sodio.","correccion":"Hiponatremia grave."},{"error":"Permitir ingesta excesiva.","correccion":"Aumenta el riesgo."},{"error":"No suspender en enfermedad aguda.","correccion":"Riesgo de hiponatremia."}],"comprueba":[{"pregunta":"¿Qué hormona reemplaza?","respuesta":"La vasopresina."},{"pregunta":"¿Qué riesgo principal tiene?","respuesta":"Hiponatremia."},{"pregunta":"¿Qué se controla?","respuesta":"Sodio y diuresis."}],"resumen":["La desmopresina reduce la diuresis.","La hiponatremia es el riesgo principal.","La educación sobre líquidos es clave.","El sodio se monitoriza."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Minirin 0,1 mg comprimidos (desmopresina).","url":"https://cima.aemps.es/cima/dochtml/ft/62142/FT_62142.html"}],"imagenes":[{"ubicacion":"Hipófisis","descripcion":"Desmopresina y control del sodio.","alt":"Desmopresina e hiponatremia"}],"keywords":["desmopresina","diabetes insípida","enuresis","hiponatremia"],"mapa":{"centro":"Desmopresina","ramas":[{"titulo":"Indicaciones","icono":"Target","nodos":["Diabetes insípida","Enuresis","Hemofilia"]},{"titulo":"Vías","icono":"Pill","nodos":["Oral","Nasal","Subcutánea"]},{"titulo":"Riesgo","icono":"AlertTriangle","nodos":["Hiponatremia","Convulsión","Sed"]},{"titulo":"Control","icono":"TestTube","nodos":["Sodio","Diuresis","Peso"]}]},"proceso":{"titulo":"Checklist de desmopresina","intro":"","pasos":[{"titulo":"Indicación","detalle":"Diabetes insípida o enuresis.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Vía","detalle":"Oral, nasal o subcutánea.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Sodio","detalle":"Basal y control.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Líquidos","detalle":"Restricción y sed.","icono":"Droplets","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Diuresis y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Niño con enuresis","contexto":"Niño con enuresis nocturna que recibe desmopresina y bebe mucha agua antes de dormir.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Ignorar la ingesta.","correcta":false,"retro":"Riesgo de hiponatremia."},{"texto":"Educar sobre restricción y controlar sodio.","correcta":true,"retro":"Previene complicaciones."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Aumenta el riesgo."}]}}$j$::jsonb;
