  -- 10. Introducción a la unidad: estrógenos, progestágenos y andrógenos
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Hormonas con múltiples efectos","texto":"Los estrógenos, los progestágenos y los andrógenos regulan la reproducción, el hueso, el metabolismo y el riesgo vascular. Sus fármacos tienen beneficios y riesgos que dependen del contexto. La elección nunca es automática."},"objetivos":["Reconocer el eje hipotálamo-hipófisis-gonadal.","Diferenciar las hormonas sexuales.","Aplicar los contextos de uso.","Reconocer los riesgos."],"conceptos":[{"icono":"Network","termino":"Eje HPG","definicion":"GnRH, LH, FSH y hormonas sexuales."},{"icono":"ShieldCheck","termino":"Estrógeno","definicion":"Efectos sobre hueso, lípidos y útero."},{"icono":"Pill","termino":"Progestágeno","definicion":"Protege el endometrio y regula el ciclo."},{"icono":"Activity","termino":"Andrógeno","definicion":"Testosterona y efectos virilizantes."}],"secciones":[{"titulo":"El eje HPG","parrafos":["El hipotálamo secreta GnRH, que estimula la hipófisis para liberar LH y FSH. En la mujer, estas hormonas regulan la ovulación y la producción de estrógenos y progestágenos. En el hombre, la LH estimula la testosterona y la FSH la espermatogénesis.","La retroalimentación negativa y positiva explica el ciclo menstrual y la regulación de la fertilidad. Los anticonceptivos hormonales modifican este eje de forma reversible."]},{"titulo":"Efectos y contextos","parrafos":["Los estrógenos mejoran el hueso y el perfil lipídico, pero aumentan el riesgo tromboembólico y endometrial cuando se usan sin progestágeno en mujeres con útero. Los progestágenos protegen el endometrio y tienen efectos variables según la molécula.","La testosterona se usa en el hipogonadismo masculino y tiene efectos sobre la masa muscular, el hueso y la libido. Su uso indebido fuera de indicación es un problema de salud pública."]},{"titulo":"Riesgos y decisión","parrafos":["La anticoncepción hormonal, la terapia de la menopausia y la testosterona comparten la necesidad de evaluar el riesgo individual: tabaquismo, migraña con aura, trombosis, cáncer hormonodependiente, hipertensión y edad.","El QF revisa los criterios de elegibilidad, las interacciones y la adherencia. La educación sobre beneficios y riesgos permite una decisión informada."]}],"errores":[{"error":"Usar estrógeno sin progestágeno con útero.","correccion":"Riesgo endometrial."},{"error":"Ignorar el tabaco.","correccion":"Aumenta el riesgo trombótico."},{"error":"Usar testosterona sin indicación.","correccion":"Riesgo y uso indebido."}],"comprueba":[{"pregunta":"¿Qué hormona regula la ovulación?","respuesta":"LH y FSH."},{"pregunta":"¿Qué protege el endometrio?","respuesta":"El progestágeno."},{"pregunta":"¿Qué se evalúa antes de indicar?","respuesta":"Riesgo trombótico y hormonal."}],"resumen":["El eje HPG regula la reproducción.","Estrógenos y progestágenos tienen efectos distintos.","La testosterona tiene indicaciones precisas.","La decisión depende del riesgo individual."],"referencias":[{"cita":"Organización Mundial de la Salud. Criterios médicos de elegibilidad para el uso de anticonceptivos. 5.ª ed. Ginebra: OMS; 2015.","url":"https://www.who.int/publications/i/item/9789241549158"}],"imagenes":[{"ubicacion":"Unidad 5","descripcion":"Eje HPG y hormonas sexuales.","alt":"Estrógenos, progestágenos y andrógenos"}],"keywords":["hormonas sexuales","estrógenos","progestágenos","testosterona","eje hpg"],"mapa":{"centro":"Hormonas sexuales","ramas":[{"titulo":"Eje","icono":"Network","nodos":["GnRH","LH","FSH"]},{"titulo":"Estrógenos","icono":"ShieldCheck","nodos":["Hueso","Lípidos","Endometrio"]},{"titulo":"Progestágenos","icono":"Pill","nodos":["Endometrio","Ovulación","Ciclo"]},{"titulo":"Andrógenos","icono":"Activity","nodos":["Testosterona","Masa muscular","Libido"]}]},"proceso":{"titulo":"Evaluar hormonas sexuales","intro":"","pasos":[{"titulo":"Contexto","detalle":"Anticoncepción, menopausia o hipogonadismo.","icono":"Target","evidencia":"Ficha."},{"titulo":"Riesgo","detalle":"Trombosis, tabaco y cáncer.","icono":"AlertTriangle","evidencia":"Historia."},{"titulo":"Elegir","detalle":"Molécula y vía.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Educar","detalle":"Beneficios y riesgos.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Tolerancia y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Estradiol sin progestágeno","contexto":"Mujer con útero que recibe estradiol solo para síntomas de menopausia.","pregunta":"¿Qué falta?","opciones":[{"texto":"Un progestágeno para proteger el endometrio.","correcta":true,"retro":"Reduce el riesgo endometrial."},{"texto":"Nada; el estradiol es suficiente.","correcta":false,"retro":"Aumenta el riesgo endometrial."},{"texto":"Testosterona.","correcta":false,"retro":"No es la indicación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: estrógenos, progestágenos y andrógenos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: estrógenos, progestágenos y andrógenos$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (149_experiencias_farmacologia_endocrina_3.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacología Endocrina$t$, v_n;
END $exp$;
